-- Mensagem de pagamento em atraso no formato dos checkpoints (mesma apresentação), com versões
-- 1 a 3 (2 e 3 em branco) e a versão Iteano. O texto não muda com o tratamento.
update modelos_mensagem set
  partes = '[{"rotulo": "Saudação e apresentação", "texto": "{saudacao}, {nome}, tudo bem? Me chamo Rafael e sou o diretor de captação do CASD."}, {"rotulo": "O que aconteceu", "texto": "Estou passando para avisar que houve um erro no processamento do seu apoio ao curso este mês. Às vezes é só algum problema com o banco ou um cartão desatualizado."}, {"rotulo": "Ajuda", "texto": "Quer que eu te ajude a resolver? É bem simples: posso te mandar o link para atualizar os dados de pagamento."}]'::jsonb,
  variacoes = '{"1": {"m": [{"rotulo": "Saudação e apresentação", "texto": "{saudacao}, {nome}, tudo bem? Me chamo Rafael e sou o diretor de captação do CASD."}, {"rotulo": "O que aconteceu", "texto": "Estou passando para avisar que houve um erro no processamento do seu apoio ao curso este mês. Às vezes é só algum problema com o banco ou um cartão desatualizado."}, {"rotulo": "Ajuda", "texto": "Quer que eu te ajude a resolver? É bem simples: posso te mandar o link para atualizar os dados de pagamento."}], "f": [{"rotulo": "Saudação e apresentação", "texto": "{saudacao}, {nome}, tudo bem? Me chamo Rafael e sou o diretor de captação do CASD."}, {"rotulo": "O que aconteceu", "texto": "Estou passando para avisar que houve um erro no processamento do seu apoio ao curso este mês. Às vezes é só algum problema com o banco ou um cartão desatualizado."}, {"rotulo": "Ajuda", "texto": "Quer que eu te ajude a resolver? É bem simples: posso te mandar o link para atualizar os dados de pagamento."}]}, "2": {"m": [{"rotulo": "Saudação e apresentação", "texto": ""}, {"rotulo": "O que aconteceu", "texto": ""}, {"rotulo": "Ajuda", "texto": ""}], "f": [{"rotulo": "Saudação e apresentação", "texto": ""}, {"rotulo": "O que aconteceu", "texto": ""}, {"rotulo": "Ajuda", "texto": ""}]}, "3": {"m": [{"rotulo": "Saudação e apresentação", "texto": ""}, {"rotulo": "O que aconteceu", "texto": ""}, {"rotulo": "Ajuda", "texto": ""}], "f": [{"rotulo": "Saudação e apresentação", "texto": ""}, {"rotulo": "O que aconteceu", "texto": ""}, {"rotulo": "Ajuda", "texto": ""}]}, "4": {"m": [{"rotulo": "Saudação e apresentação", "texto": "Saudações Iteanas, {apelido}, seu bixo da T30 e diretor de captação do CASD aqui!"}, {"rotulo": "O que aconteceu", "texto": "Estou passando para avisar que houve um erro no processamento do seu apoio ao curso este mês. Às vezes é só algum problema com o banco ou um cartão desatualizado."}, {"rotulo": "Ajuda", "texto": "Quer que eu te ajude a resolver? É bem simples: posso te mandar o link para atualizar os dados de pagamento."}], "f": [{"rotulo": "Saudação e apresentação", "texto": "Saudações Iteanas, {apelido}, seu bixo da T30 e diretor de captação do CASD aqui!"}, {"rotulo": "O que aconteceu", "texto": "Estou passando para avisar que houve um erro no processamento do seu apoio ao curso este mês. Às vezes é só algum problema com o banco ou um cartão desatualizado."}, {"rotulo": "Ajuda", "texto": "Quer que eu te ajude a resolver? É bem simples: posso te mandar o link para atualizar os dados de pagamento."}]}}'::jsonb
where chave = 'cobranca';

update modelos_mensagem set texto = (select string_agg(p->>'texto', E'\n\n' order by i) from jsonb_array_elements(partes) with ordinality as t(p, i))
where chave = 'cobranca';
